cd /workspace/tests && python3 - <<'PYEOF'
import sys, json, random
sys.path.insert(0, "/workspace/tests")
from run_sub import run
random.seed(1234)
names = ["a.t.","b.t.","c.t.","x.y.t.","t.","*.t."]
types = ["A","AAAA","TXT","CNAME"]
for trial in range(31):
    zrecs = []
    for _ in range(random.randint(0,6)):
        owner = random.choice(names)
        ty = random.choice(types)
        if ty == "A": data = "%d.%d.%d.%d" % tuple(random.randint(0,255) for _ in range(4))
        elif ty == "AAAA": data = "2001:db8::%d" % random.randint(0,9)
        elif ty == "TXT": data = "t%d" % random.randint(0,99)
        else: data = random.choice(names)
        zrecs.append({"owner":owner,"type":ty,"data":data})
    byowner = {}
    bad = False
    for r in zrecs:
        byowner.setdefault(r["owner"], set()).add(r["type"])
    for o, ts in byowner.items():
        if "CNAME" in ts and len(ts) > 1: bad = True
        if "CNAME" in ts and o == "t.": bad = True
    if bad: continue
    profiles = []
    for i in range(random.randint(1,5)):
        profiles.append({"id":"p%d"%i,"max_aliases":random.randint(0,3),
                         "cname":random.choice(["follow","stop"]),
                         "wildcard":random.choice(["rfc","off","one-label"])})
    queries = []
    for i in range(random.randint(0,7)):
        queries.append({"id":"q%d"%i,"name":random.choice(names),
                        "type":random.choice(types),"cost":random.randint(1,9)})
    doc = {"zones":[{"origin":"t.","records":zrecs}],"profiles":profiles,
           "queries":queries,"observations":[]}
    if trial == 30:
        print(json.dumps(doc, indent=1))
        print(run(doc))
PYEOF
